// convItem carries one value between the two copies of the contract.
func convItem(v remoteapi.Item) database.Item {
	return database.Item{
		Name:     v.Name,
		Type:     v.Type,
		Required: v.Required,
		Target:   v.Target,
		Itens:    convSliceItem(v.Itens),
	}
}

// convSchemaInstance carries one value between the two copies of the contract.
func convSchemaInstance(v remoteapi.SchemaInstance) database.SchemaInstance {
	return database.SchemaInstance{
		Items:  convSliceItem(v.Items),
		Prefix: v.Prefix,
		NewItem: func(p0 map[string]any) (database.SchemaItem, *database.Error) {
			r0, r1 := v.NewItem(p0)
			return convSchemaItem(r0), convPtrError(r1)
		},
		FindByKey: func(p0 string, p1 any) (database.SchemaItem, bool) {
			r0, r1 := v.FindByKey(p0, p1)
			return convSchemaItem(r0), r1
		},
		FindById: func(p0 int64) (database.SchemaItem, bool) {
			r0, r1 := v.FindById(p0)
			return convSchemaItem(r0), r1
		},
		ListAll: func() ([]database.SchemaItem, *database.Error) {
			r0, r1 := v.ListAll()
			return convSliceSchemaItem(r0), convPtrError(r1)
		},
		List: func(p0 int, p1 int) ([]database.SchemaItem, *database.Error) {
			r0, r1 := v.List(p0, p1)
			return convSliceSchemaItem(r0), convPtrError(r1)
		},
	}
}

// convSchemaItem carries one value between the two copies of the contract.
func convSchemaItem(v remoteapi.SchemaItem) database.SchemaItem {
	return database.SchemaItem{
		Items:  convSliceItem(v.Items),
		Prefix: v.Prefix,
		Id:     v.Id,
		Get: func(p0 string) (any, *database.Error) {
			r0, r1 := v.Get(p0)
			return r0, convPtrError(r1)
		},
		GetLink: func(p0 string) (database.SchemaItem, bool) {
			r0, r1 := v.GetLink(p0)
			return convSchemaItem(r0), r1
		},
		Update:            func(p0 string, p1 any) *database.Error { return convPtrError(v.Update(p0, p1)) },
		Remove:            func() *database.Error { return convPtrError(v.Remove()) },
		CheckKeysPresence: v.CheckKeysPresence,
		ListAll:           func(p0 string) []database.SchemaItem { return convSliceSchemaItem(v.ListAll(p0)) },
		NewSubItem: func(p0 string, p1 map[string]any) (database.SchemaItem, *database.Error) {
			r0, r1 := v.NewSubItem(p0, p1)
			return convSchemaItem(r0), convPtrError(r1)
		},
		String: v.String,
	}
}

// convPtrError carries one value between the two copies of the contract.
func convPtrError(v *remoteapi.Error) *database.Error {
	if v == nil {
		return nil
	}

	out := convError(*v)
	return &out
}

// convError carries one value between the two copies of the contract.
func convError(v remoteapi.Error) database.Error {
	return database.Error{
		Type:     v.Type,
		Key:      v.Key,
		KeyValue: v.KeyValue,
		Message:  v.Message,
	}
}

// convSliceSchemaItem carries one value between the two copies of the contract.
func convSliceSchemaItem(v []remoteapi.SchemaItem) []database.SchemaItem {
	if v == nil {
		return nil
	}

	out := make([]database.SchemaItem, len(v))
	for index := range v {
		out[index] = convSchemaItem(v[index])
	}

	return out
}

// convInfo carries one value between the two copies of the contract.
func convInfo(v remoteapi.Info) database.Info {
	return database.Info{
		Name:    v.Name,
		Version: v.Version,
	}
}
